import {isLoggedIn} from '@github-ui/client-env'
import {defaultFilterConfig} from '@github-ui/filter-core/constants/defaults'
import {FilterQueryParser} from '@github-ui/filter-core/parser'
import {OrgFilterProvider} from '@github-ui/filter-core/providers/org'
import {RepositoryFilterProvider} from '@github-ui/filter-core/providers/repository'
import {useQuery} from '@github-ui/react-query'
import {useMemo} from 'react'

import {
  FILTER_PROVIDER_OPTIONS,
  MAX_INITIAL_PER_TYPE,
  MAX_LOGGED_OUT_SUGGESTIONS,
  MAX_SUGGESTIONS_PER_TYPE,
} from '../consts/config'
import type {QuickSearchSuggestion} from '../quick-search-types'
import {buildRenderedGroups} from './build-rendered-groups'
import {filterExplorePages} from './filter-explore-pages'
import {getContextualSuggestions} from './get-contextual-suggestions'
import {copilotChatSuggestion, getRecentSearchSuggestions} from './initial-suggestions'
import {codeSearchSuggestionsQueryOptions} from './queries/code-search-suggestions-query'
import {orgSuggestionsQueryOptions} from './queries/org-suggestions-query'
import {repoSuggestionsQueryOptions} from './queries/repo-suggestions-query'
import {savedSearchSuggestionsQueryOptions} from './queries/saved-search-suggestions-query'
import {parseQuery} from './suggestion-utils'

/**
 * Manages the async suggestion lifecycle for the QuickSearch dialog.
 *
 * Implements stale-while-revalidate: cached suggestions for the current
 * `lastSegment` key are shown immediately, then silently replaced once a
 * fresh fetch resolves. The three suggestion modes are:
 *
 * 1. **Empty segment** (`query` is empty or ends with a space): shows default
 *    suggestions — recent searches, top orgs/repos, and Copilot.
 * 2. **Prefixed segment** (`org:…` or `repo:…`): only the matching provider
 *    is queried; results are returned as autocomplete tokens.
 * 3. **Plain text**: both providers are queried in parallel so the user sees
 *    matching orgs and repos before committing to a filter scope.
 *
 * The hook composes results from multiple providers (orgs, repos, code search,
 * contextual suggestions, and any caller-supplied suggestions) into:
 *
 * - `groupedSuggestions`: sections suitable for rendering grouped lists.
 * - `flatSuggestions`: a flattened, ordered list derived from the groups,
 *   useful for consumers that manage selection / keyboard navigation.
 */
export function useQuickSearchSuggestions(
  query: string,
  caretPosition: number,
  isOpen: boolean,
  additionalSuggestions?: QuickSearchSuggestion[],
  searchContext?: Record<string, string>,
) {
  // Per-component providers with isolated internal caches — important so that
  // each component instance (and each test) gets fresh network calls, and so
  // that the providers' shared abortSuggestionsController cannot be mutated by
  // the module-level pre-warm while the user is actively typing.
  const {orgProvider, repoProvider, parser} = useMemo(() => {
    const org = new OrgFilterProvider(FILTER_PROVIDER_OPTIONS)
    const repo = new RepositoryFilterProvider(FILTER_PROVIDER_OPTIONS)
    return {orgProvider: org, repoProvider: repo, parser: new FilterQueryParser([org, repo], defaultFilterConfig)}
  }, [])

  const parsedQuery = parseQuery(query, caretPosition)

  const repoSuggestionsQuery = useQuery({
    ...repoSuggestionsQueryOptions(parsedQuery, repoProvider, parser),
    enabled: isOpen && isLoggedIn(),
  })

  const orgSuggestionsQuery = useQuery({
    ...orgSuggestionsQueryOptions(parsedQuery, orgProvider, parser),
    enabled: isOpen && isLoggedIn(),
  })

  const codeSearchSuggestionsQuery = useQuery({
    ...codeSearchSuggestionsQueryOptions(parsedQuery),
    enabled: isOpen && isLoggedIn(),
  })

  const savedSearchSuggestionsQuery = useQuery({
    ...savedSearchSuggestionsQueryOptions(parsedQuery),
    enabled: isOpen && isLoggedIn(),
  })

  const flatSuggestions = useMemo(() => {
    if (!isOpen) return null

    if (!isLoggedIn()) return filterExplorePages(parsedQuery.value).slice(0, MAX_LOGGED_OUT_SUGGESTIONS)

    // Initial loading state
    if (!repoSuggestionsQuery.data || !orgSuggestionsQuery.data) return null

    // ── Empty/no active segment: show initial / default suggestions ──────────────────
    if (!parsedQuery.activeSegment) {
      const initial = [
        ...(savedSearchSuggestionsQuery.data?.slice(0, MAX_INITIAL_PER_TYPE) ?? []),
        ...getRecentSearchSuggestions(),
        ...(repoSuggestionsQuery.data?.slice(0, MAX_INITIAL_PER_TYPE) ?? []),
        ...(orgSuggestionsQuery.data?.slice(0, MAX_INITIAL_PER_TYPE) ?? []),
        ...(codeSearchSuggestionsQuery.data?.slice(0, MAX_INITIAL_PER_TYPE) ?? []),
        ...(additionalSuggestions ?? []),
        copilotChatSuggestion,
      ]

      // When the query already scopes to a specific org or repo, suppress
      // unrelated jump-to suggestions to avoid noise.
      const filtered = initial.filter(s => {
        if (parsedQuery.hasOrgFilter && s.group === 'organizations' && s.action === 'jump-to') return false
        if (parsedQuery.hasRepoFilter && s.group === 'repositories' && s.action === 'jump-to') return false
        return true
      })

      return filtered
    }

    return [
      ...(savedSearchSuggestionsQuery.data?.slice(0, MAX_SUGGESTIONS_PER_TYPE) ?? []),
      ...(repoSuggestionsQuery.data?.slice(0, MAX_SUGGESTIONS_PER_TYPE) ?? []),
      ...(orgSuggestionsQuery.data?.slice(0, MAX_SUGGESTIONS_PER_TYPE) ?? []),
      ...(codeSearchSuggestionsQuery.data?.slice(0, MAX_SUGGESTIONS_PER_TYPE) ?? []),
      ...(additionalSuggestions ?? []),
      ...getContextualSuggestions(parsedQuery, searchContext),
    ]
  }, [
    additionalSuggestions,
    isOpen,
    parsedQuery,
    orgSuggestionsQuery.data,
    repoSuggestionsQuery.data,
    codeSearchSuggestionsQuery.data,
    savedSearchSuggestionsQuery.data,
    searchContext,
  ])

  const [groupedSuggestions, flatOrderedSuggestions] = useMemo(() => {
    if (!flatSuggestions) return [null, null]

    const groups = buildRenderedGroups(flatSuggestions)

    return [groups, groups.flatMap(group => group.items.map(item => item.suggestion))]
  }, [flatSuggestions])

  return {flatSuggestions: flatOrderedSuggestions, groupedSuggestions}
}
