import {BlockType, defaultFilterConfig, type FilterQueryParser, type MutableFilterBlock} from '@github-ui/filter-core'
import type {OrgFilterProvider} from '@github-ui/filter-core/providers'
import {queryOptions} from '@github-ui/react-query'

import {mapOrgSuggestion} from '../map-suggestions'
import {isValueSuggestion, type ParsedQuery} from '../suggestion-utils'

/** Query options for fetching organization suggestions */
export function orgSuggestionsQueryOptions(query: ParsedQuery, provider: OrgFilterProvider, parser: FilterQueryParser) {
  // If the active segment is empty, fetch the empty orgs query
  const orgQueryValue = !query.activeSegment
    ? ''
    : // If the active segment is an org filter or plain text, use it as the query; otherwise, don't run the query at all (undefined)
      query.activeSegment.type === 'org' || query.activeSegment.type === 'plain'
      ? query.activeSegment.value
      : undefined

  return queryOptions({
    // If we include the provider in the key, we won't be able to reuse the preloaded data, which defeats the preloading
    // eslint-disable-next-line @tanstack/query/exhaustive-deps
    queryKey: ['quick-search-org-suggestions', orgQueryValue],
    queryFn: async () => {
      if (orgQueryValue === undefined) return []

      const fq = parser.parse('', undefined, 0)
      const block: MutableFilterBlock = {
        id: 0,
        type: BlockType.Filter,
        raw: orgQueryValue,
        key: {value: 'org', valid: true},
        provider,
        value: {raw: orgQueryValue, values: [{value: orgQueryValue}]},
      }

      const orgSuggestions = await provider.getSuggestions(fq, block, defaultFilterConfig, null)
      return orgSuggestions ?? []
    },
    // Mapping in select instead of queryFn allows reusing the same data for both autocomplete and navigation suggestions
    select: data => data.filter(isValueSuggestion).map(s => mapOrgSuggestion(s, query.activeSegment?.type === 'org')),
    staleTime: 60 * 1000,
    placeholderData: prev => prev,
  })
}
