import {Link} from '@primer/react'

import styles from './footer.module.css'
import type {QuickSearchProps} from './quick-search-types'

type QuickSearchFooterProps = {
  links: NonNullable<QuickSearchProps['footerLinks']>
}

export function QuickSearchFooter({links}: QuickSearchFooterProps) {
  return (
    <div className={styles.footer}>
      {links.searchSyntaxTips ? (
        <Link href={links.searchSyntaxTips} inline={false}>
          Search syntax tips
        </Link>
      ) : (
        <span />
      )}
      {links.feedback && (
        <Link href={links.feedback} inline={false}>
          Give feedback
        </Link>
      )}
    </div>
  )
}
