import type {SymbolKind} from '@github-ui/code-nav'
import {GitHubAvatar} from '@github-ui/github-avatar'
import {ActionList, useId} from '@primer/react'
import {memo} from 'react'

import type {QuickSearchSuggestion} from './quick-search-types'
import styles from './suggestion-item.module.css'
import {getActionLabel, tokenizeFilterText} from './suggestions/suggestion-utils'

type SuggestionLeadingVisualProps = {suggestion: QuickSearchSuggestion}

function SuggestionLeadingVisual({suggestion}: SuggestionLeadingVisualProps) {
  const IconComponent = suggestion.icon
  if (suggestion.avatarUrl) {
    return <GitHubAvatar src={suggestion.avatarUrl} alt="" size={16} square />
  }
  return <IconComponent size={16} className={styles.suggestionIcon} />
}

function SymbolKindLabel({kind}: {kind: SymbolKind}) {
  const colorVar = `var(--color-${kind.plColor.split('.').join('-')})`
  return (
    <span
      className={styles.symbolIndicator}
      style={{background: `color-mix(in srgb, ${colorVar} 10%, transparent)`, color: colorVar}}
    >
      {kind.fullName}
    </span>
  )
}

function HighlightedDisplayName({text}: {text: string}) {
  const segments = tokenizeFilterText(text)
  if (segments.length === 0) return <>{text}</>
  return (
    <>
      {segments.map((seg, i) => {
        if (seg.type === 'filter-value') {
          return (
            <span key={i} className={styles.filterValue}>
              {seg.text}
            </span>
          )
        }
        return <span key={i}>{seg.text}</span>
      })}
    </>
  )
}

export type SuggestionItemProps = {
  suggestion: QuickSearchSuggestion
  isActive: boolean
  htmlId: string
  /** Called when an autocomplete suggestion is activated; receives the value to insert. */
  onAutocomplete: (insertValue: string) => void
  /** Called when a jump-to or search suggestion is activated. */
  onSelect: (suggestion: QuickSearchSuggestion) => void
}

export const SuggestionItem = memo(function SuggestionItemImpl({
  suggestion,
  htmlId,
  isActive,
  onAutocomplete,
  onSelect,
}: SuggestionItemProps) {
  const actionLabel = getActionLabel(suggestion)

  function handleSelect() {
    if (suggestion.action === 'autocomplete') {
      if (suggestion.insertValue !== undefined) {
        onAutocomplete(suggestion.insertValue)
      }
    } else {
      onSelect(suggestion)
    }
  }

  const hiddenLabelId = useId()
  const hiddenLabel = (
    <span className="sr-only" id={hiddenLabelId}>
      {suggestion.ariaLabel}
    </span>
  )

  const ActionListItem = suggestion.action === 'autocomplete' ? ActionList.Item : ActionList.LinkItem

  return (
    <ActionListItem
      id={htmlId}
      data-testid="quick-search-suggestion"
      role="option"
      aria-selected={isActive}
      aria-label={suggestion.ariaLabel}
      active={isActive}
      onSelect={handleSelect}
      aria-labelledby={hiddenLabelId}
      href={suggestion.href}
    >
      {/* eslint-disable-next-line primer-react/direct-slot-children */}
      <ActionList.LeadingVisual>
        <SuggestionLeadingVisual suggestion={suggestion} />
      </ActionList.LeadingVisual>
      {suggestion.symbolKind && (
        <>
          <SymbolKindLabel kind={suggestion.symbolKind} />{' '}
        </>
      )}
      <span className={styles.suggestionName}>
        <HighlightedDisplayName text={suggestion.displayName} />
      </span>
      {hiddenLabel}
      {suggestion.description ? (
        // eslint-disable-next-line primer-react/direct-slot-children
        <ActionList.Description variant="block">{suggestion.description}</ActionList.Description>
      ) : null}
      {actionLabel && (
        // eslint-disable-next-line primer-react/direct-slot-children
        <ActionList.TrailingVisual className={styles.actionLabel}>{actionLabel}</ActionList.TrailingVisual>
      )}
    </ActionListItem>
  )
})
