import {BlockType, defaultFilterConfig, type FilterQueryParser, type MutableFilterBlock} from '@github-ui/filter-core'
import type {RepositoryFilterProvider} from '@github-ui/filter-core/providers'
import {queryOptions} from '@github-ui/react-query'

import {mapRepoSuggestion} from '../map-suggestions'
import {isValueSuggestion, type ParsedQuery} from '../suggestion-utils'

/** Query options for fetching repository suggestions */
export function repoSuggestionsQueryOptions(
  query: ParsedQuery,
  provider: RepositoryFilterProvider,
  parser: FilterQueryParser,
) {
  // If the active segment is empty, fetch the empty repos query
  const repoQueryValue = !query.activeSegment
    ? ''
    : // If the active segment is a repo filter or plain text, use it as the query; otherwise, don't run the query at all (undefined)
      query.activeSegment.type === 'repo' || query.activeSegment.type === 'plain'
      ? query.activeSegment.value
      : undefined

  return queryOptions({
    // If we include the provider in the key, we won't be able to reuse the preloaded data, which defeats the preloading
    // eslint-disable-next-line @tanstack/query/exhaustive-deps
    queryKey: ['quick-search-repo-suggestions', repoQueryValue],
    queryFn: async () => {
      if (repoQueryValue === undefined) return []

      const fq = parser.parse('', undefined, 0)
      const block: MutableFilterBlock = {
        id: 0,
        type: BlockType.Filter,
        raw: repoQueryValue,
        key: {value: 'repo', valid: true},
        provider,
        value: {raw: repoQueryValue, values: [{value: repoQueryValue}]},
      }

      const repoSuggestions = await provider.getSuggestions(fq, block, defaultFilterConfig, null)
      return repoSuggestions ?? []
    },
    // Mapping in select instead of queryFn allows reusing the same data for both autocomplete and navigation suggestions
    select: data => data.filter(isValueSuggestion).map(s => mapRepoSuggestion(s, query.activeSegment?.type === 'repo')),
    staleTime: 60 * 1000,
    placeholderData: prev => prev,
  })
}
