import type {SymbolKind} from '@github-ui/code-nav'
import type {Icon} from '@primer/octicons-react'
import {Dialog} from '@primer/react'
import type {ComponentProps} from 'react'

// ─── Suggestion types ─────────────────────────────────────────────────────────

/**
 * Describes what happens when the user activates a suggestion:
 * - `jump-to`: Navigate directly to an entity's profile page.
 * - `search`: Run a full GitHub search for the query.
 * - `autocomplete`: Insert a filter token (e.g. `org:github `) and keep the dialog open.
 */
export type SuggestionAction = 'jump-to' | 'search' | 'autocomplete'

/** Which visual group a suggestion belongs to in the dropdown list. */
export type SuggestionGroup =
  | 'saved'
  | 'contextual'
  | 'recent'
  | 'repositories'
  | 'organizations'
  | 'suggestions'
  | 'code'

/**
 * A single item displayed in the QuickSearch suggestion list.
 * Consumers can supply extra suggestions via `QuickSearchProps.additionalSuggestions`.
 */
export type QuickSearchSuggestion = {
  /** Stable key used for React reconciliation and ARIA option IDs. */
  id: string
  /** Text shown as the primary label in the dropdown row. */
  displayName: string
  /** Description text shown below the primary label in the dropdown row. */
  description?: string
  /** Raw search query string, used to persist recent searches (action: 'search' only). */
  searchQuery?: string
  /** Navigation target for `jump-to` and `search` actions. */
  href?: string
  /**
   * Value inserted into the search input when the suggestion is activated
   * (action: `autocomplete` only). Should include a trailing space so the next
   * filter token can be typed immediately.
   */
  insertValue?: string
  /** Screen-reader label for the option element. */
  ariaLabel: string
  action: SuggestionAction
  /** URL for the entity's avatar image. Falls back to `icon` when undefined or broken. */
  avatarUrl?: string
  /** Octicon component rendered as the fallback leading visual. */
  icon: Icon
  group: SuggestionGroup
  customActionLabel?: string
  /** The kind of symbol (e.g., function, variable) for code suggestions only. */
  symbolKind?: SymbolKind
}

/** Props for the `QuickSearch` dialog component. */
export type QuickSearchProps = {
  /** Controls whether the dialog is rendered and visible. */
  isOpen: boolean
  /** Called when the dialog should be closed (Escape, backdrop click, etc.). */
  onClose: () => void
  /** Element to restore focus to when the dialog closes. */
  returnFocusRef?: ComponentProps<typeof Dialog>['returnFocusRef']
  /**
   * Extra suggestions injected after the built-in repo/org results.
   * Useful for surfacing product-specific shortcuts (e.g. a Copilot entry point).
   */
  additionalSuggestions?: QuickSearchSuggestion[]
  /** Optional footer links rendered at the bottom of the dialog. */
  footerLinks?: {
    searchSyntaxTips?: string
    feedback?: string
  }
  searchContext?: Record<string, string>
  onSearchSubmit?: (query: string) => void
  onSuggestionSelect?: (suggestionType: SuggestionAction) => void
}

// ─── Suggestion grouping types ───────────────────────────────────────────────

export type GroupedSuggestion = {suggestion: QuickSearchSuggestion; flatIndex: number}
export type RenderedGroup = {label: string; items: GroupedSuggestion[]}

export const GROUP_ORDER: SuggestionGroup[] = [
  'saved',
  'contextual',
  'recent',
  'repositories',
  'organizations',
  'code',
  'suggestions',
]
export const GROUP_LABELS: Record<SuggestionGroup, string> = {
  recent: 'Recent',
  repositories: 'Repositories',
  organizations: 'Organizations',
  suggestions: 'Suggestions',
  saved: 'Saved',
  contextual: '',
  code: 'Code',
}
