import type {ARIAFilterSuggestion} from '@github-ui/filter-core'
import {OrganizationIcon, RepoIcon} from '@primer/octicons-react'

import type {QuickSearchSuggestion} from '../quick-search-types'

/**
 * @param filterMode When true the suggestion represents narrowing the filter
 *   scope (e.g. typing `org:github` → autocomplete to `org:github `) rather
 *   than navigating directly to the org profile.
 */
export function mapOrgSuggestion(s: ARIAFilterSuggestion, filterMode = false): QuickSearchSuggestion {
  const value = typeof s.value === 'string' ? s.value : s.value()
  const displayName = s.displayName ?? value
  if (filterMode) {
    return {
      id: `org-${value}`,
      icon: OrganizationIcon,
      displayName,
      insertValue: `org:${value} `,
      ariaLabel: `Autocomplete org:${value} scope, organization`,
      action: 'autocomplete',
      avatarUrl: s.avatar?.url,
      group: 'organizations',
    }
  }
  return {
    id: `org-${value}`,
    icon: OrganizationIcon,
    displayName,
    href: `/${value}`,
    ariaLabel: `Jump to ${displayName}, organization`,
    action: 'jump-to',
    avatarUrl: s.avatar?.url,
    group: 'organizations',
  }
}

