import {ScopedCommands} from '@github-ui/ui-commands'
import {ActionList, Dialog} from '@primer/react'
import {Fragment, useCallback, useId, useRef, useState} from 'react'

import {QuickSearchFooter} from './footer'
import styles from './quick-search.module.css'
import {QuickSearchInput} from './quick-search-input'
import type {QuickSearchProps, QuickSearchSuggestion} from './quick-search-types'
import {SuggestionItem} from './suggestion-item'
import {SuggestionSkeletons} from './suggestion-skeletons'
import {saveRecentSearch} from './suggestions/initial-suggestions'
import {preloadQuickSearch} from './suggestions/preload-quick-search'
import {parseQuery} from './suggestions/suggestion-utils'
import {useQuickSearchSuggestions} from './suggestions/use-quick-search-suggestions'

// re-export for lazy preload
// eslint-disable-next-line no-barrel-files/no-barrel-files
export {preloadQuickSearch} from './suggestions/preload-quick-search'

// Auto-invoke in browser environments only. Guarded so the network call is
// never triggered during SSR or test module evaluation (before fetch is mocked).
if (typeof document !== 'undefined') {
  preloadQuickSearch()
}

export function QuickSearch({
  isOpen,
  onClose,
  returnFocusRef,
  additionalSuggestions,
  footerLinks,
  searchContext,
  onSearchSubmit,
  onSuggestionSelect,
}: QuickSearchProps) {
  const searchInputRef = useRef<HTMLInputElement>(null)
  const listboxId = useId()
  const initialQueryText = searchContext?.scope ? `${searchContext.scope} ` : ''
  const [query, setQuery] = useState(initialQueryText)
  const [caretPosition, setCaretPosition] = useState(initialQueryText.length)

  const [activeItemId, setActiveItemId] = useState<string | null>(null)

  const {groupedSuggestions, flatSuggestions} = useQuickSearchSuggestions(
    query,
    caretPosition,
    isOpen,
    additionalSuggestions,
    searchContext,
  )

  const activeItem = flatSuggestions?.find(s => s.id === activeItemId) ?? null

  const handleClose = useCallback(() => {
    setQuery('')
    setActiveItemId(null)
    setCaretPosition(0)
    onClose()
  }, [onClose])

  const navigate = useCallback(
    (direction: 'up' | 'down') => {
      const suggestionsCount = flatSuggestions?.length ?? 0
      if (suggestionsCount === 0) return

      setActiveItemId(prev => {
        const i = flatSuggestions?.findIndex(s => s.id === prev) ?? -1

        const nextIndex = direction === 'up' ? Math.max(i - 1, 0) : Math.min(i + 1, suggestionsCount - 1)
        return flatSuggestions?.[nextIndex]?.id ?? null
      })
    },
    [flatSuggestions],
  )

  /** Replace the active segment (at the caret) with `insertValue`, preserving
   *  any tokens before/after it. Returns the new query and caret position. */
  const replaceActiveSegment = useCallback(
    (insertValue: string) => {
      const parsed = parseQuery(query, caretPosition)
      if (parsed.activeSegment) {
        const before = query.slice(0, parsed.activeSegment.start)
        const after = query.slice(parsed.activeSegment.end)
        const newQuery = before + insertValue + after
        const newCaret = before.length + insertValue.length
        return {newQuery, newCaret}
      }
      // No active segment — insert at caret
      const before = query.slice(0, caretPosition)
      const after = query.slice(caretPosition)
      const newQuery = before + insertValue + after
      const newCaret = before.length + insertValue.length
      return {newQuery, newCaret}
    },
    [query, caretPosition],
  )

  const selectActive = useCallback(() => {
    if (activeItem) {
      onSuggestionSelect?.(activeItem.action)
      if (activeItem.action === 'autocomplete' && activeItem.insertValue !== undefined) {
        const {newQuery, newCaret} = replaceActiveSegment(activeItem.insertValue)
        setQuery(newQuery)
        setCaretPosition(newCaret)
        setActiveItemId(null)
        const input = searchInputRef.current
        if (input) {
          requestAnimationFrame(() => {
            input.focus()
            input.setSelectionRange(newCaret, newCaret)
          })
        }
      } else if (activeItem.href) {
        if (activeItem.action === 'search') saveRecentSearch(activeItem.searchQuery ?? activeItem.displayName)
        window.location.assign(activeItem.href)
        handleClose()
      }
    } else if (query.trim()) {
      onSearchSubmit?.(query.trim())
      saveRecentSearch(query.trim())
      window.location.assign(`/search?q=${encodeURIComponent(query.trim())}`)
      handleClose()
    }
  }, [activeItem, query, handleClose, onSearchSubmit, onSuggestionSelect, replaceActiveSegment])

  // Uses activeItem, not activeItemId, because it's possible that there's an activeItemId set even if there's no
  // matching item (could have been removed) in which case we treat it as if there's no active item at all
  const activeOptionId = activeItem ? `${listboxId}-option-${activeItem.id.replaceAll(/\s/g, '{{space}}')}` : undefined
  const hasResults = flatSuggestions !== null && flatSuggestions.length > 0

  const canSelect = activeItem !== null || query.trim().length > 0

  const handleQueryChange = useCallback((newQuery: string, newCaret: number) => {
    setQuery(newQuery)
    setCaretPosition(newCaret)
  }, [])

  // Identity intentionally tracks `replaceActiveSegment` (query + caretPosition) so the inserted
  // text always lands at the current caret. During arrow navigation neither changes, so the
  // callback stays stable and the memoized SuggestionItem rows skip re-rendering.
  const onAutocomplete = useCallback(
    (insertValue: string) => {
      const {newQuery, newCaret} = replaceActiveSegment(insertValue)
      setQuery(newQuery)
      setCaretPosition(newCaret)
      const input = searchInputRef.current
      if (input) {
        requestAnimationFrame(() => {
          input.focus()
          input.setSelectionRange(newCaret, newCaret)
        })
      }
    },
    [replaceActiveSegment],
  )

  const onSelect = useCallback(
    (suggestion: QuickSearchSuggestion) => {
      onSuggestionSelect?.(suggestion.action)
      if (suggestion.action === 'search') saveRecentSearch(suggestion.searchQuery ?? suggestion.displayName)
      if (suggestion.href) window.location.assign(suggestion.href)
      handleClose()
    },
    [onSuggestionSelect, handleClose],
  )

  if (!isOpen) return null

  return (
    <ScopedCommands
      commands={
        hasResults
          ? {
              'github:up': () => navigate('up'),
              'github:down': () => navigate('down'),
              ...(canSelect ? {'github:select': () => selectActive()} : {}),
              'github:cancel': () => handleClose(),
            }
          : {}
      }
    >
      <Dialog
        onClose={handleClose}
        initialFocusRef={searchInputRef}
        returnFocusRef={returnFocusRef}
        renderHeader={({dialogLabelId}) => (
          <h1 id={dialogLabelId} className="sr-only">
            Quick search
          </h1>
        )}
        className={styles.quickSearchDialog}
      >
        <Dialog.Body className="p-0">
          <QuickSearchInput
            query={query}
            onQueryChange={handleQueryChange}
            listboxId={listboxId}
            activeOptionId={activeOptionId}
            hasResults={hasResults}
            inputRef={searchInputRef}
          />
          <ActionList id={listboxId} role="listbox" aria-label="Search suggestions" variant="horizontal-inset">
            {groupedSuggestions === null ? (
              <SuggestionSkeletons />
            ) : (
              groupedSuggestions.map((group, i) => (
                <Fragment key={group.label}>
                  {i > 0 && <ActionList.Divider />}
                  <ActionList.Group>
                    {group.label && <ActionList.GroupHeading>{group.label}</ActionList.GroupHeading>}

                    {group.items.map(({suggestion}) => {
                      const suggestionId = suggestion.id.replaceAll(/\s/g, '{{space}}')
                      return (
                        <SuggestionItem
                          key={suggestionId}
                          suggestion={suggestion}
                          htmlId={`${listboxId}-option-${suggestionId}`}
                          isActive={suggestion.id === activeItemId}
                          onAutocomplete={onAutocomplete}
                          onSelect={onSelect}
                        />
                      )
                    })}
                  </ActionList.Group>
                </Fragment>
              ))
            )}
          </ActionList>
          {footerLinks && <QuickSearchFooter links={footerLinks} />}
        </Dialog.Body>
      </Dialog>
    </ScopedCommands>
  )
}
