import {SearchIcon, XCircleFillIcon} from '@primer/octicons-react'
import {TextInput} from '@primer/react'
import type {RefObject} from 'react'

import styles from './quick-search-input.module.css'
import {tokenizeFilterText} from './suggestions/suggestion-utils'

export type QuickSearchInputProps = {
  query: string
  onQueryChange: (query: string, caretPosition: number) => void
  listboxId: string
  activeOptionId: string | undefined
  /** Whether any suggestions are currently displayed (controls aria-expanded). */
  hasResults: boolean
  inputRef: RefObject<HTMLInputElement | null>
}

function HighlightedText({text}: {text: string}) {
  const segments = tokenizeFilterText(text)
  if (segments.length === 0) return null
  return (
    <>
      {segments.map((seg, i) => {
        if (seg.type === 'filter-value') {
          return (
            <span key={i} className={styles.filterValue}>
              {seg.text}
            </span>
          )
        }
        return <span key={i}>{seg.text}</span>
      })}
    </>
  )
}

export function QuickSearchInput({
  query,
  onQueryChange,
  listboxId,
  activeOptionId,
  hasResults,
  inputRef,
}: QuickSearchInputProps) {
  function deferFocusInput() {
    const input = inputRef.current
    if (!input) return
    requestAnimationFrame(() => input.focus())
  }

  function clearInput() {
    onQueryChange('', 0)
    deferFocusInput()
  }

  // The clear button is wrapped in a ScopedCommands subtree that maps Enter to
  // `github:select` (which submits a search and closes the dialog). Because
  // ScopedCommands uses a native DOM listener on an ancestor element, React's
  // delegated handlers can't intercept the event in time. Attach a native
  // `keydown` listener directly on the button via a ref callback so the
  // browser's default Enter/Space → click activation proceeds normally.
  const attachClearButtonActivationGuard = (button: HTMLButtonElement | null) => {
    if (!button) return
    const handler = (event: KeyboardEvent) => {
      // eslint-disable-next-line @github-ui/ui-commands/no-manual-shortcut-logic -- guarding native button-activation keys, not defining a shortcut
      if (event.key === 'Enter' || event.key === ' ') {
        event.stopPropagation()
      }
    }
    button.addEventListener('keydown', handler)
    return () => button.removeEventListener('keydown', handler)
  }

  function handleChange(e: React.ChangeEvent<HTMLInputElement>) {
    const input = e.target
    onQueryChange(input.value, input.selectionStart ?? input.value.length)
  }

  function handleCaretMove(e: React.SyntheticEvent<HTMLInputElement>) {
    const input = e.currentTarget
    onQueryChange(input.value, input.selectionStart ?? input.value.length)
  }

  return (
    <div className={styles.searchContainer}>
      <div className={styles.inputWrapper}>
        <div className={styles.inputOverlay} aria-hidden="true">
          <HighlightedText text={query} />
        </div>
        <TextInput
          className={styles.input}
          ref={inputRef}
          value={query}
          onChange={handleChange}
          onKeyUp={handleCaretMove}
          onClick={handleCaretMove}
          onSelect={handleCaretMove}
          placeholder="Search or jump to..."
          role="combobox"
          aria-haspopup="listbox"
          aria-expanded={hasResults}
          aria-controls={listboxId}
          aria-autocomplete="list"
          aria-activedescendant={activeOptionId}
          leadingVisual={<SearchIcon />}
          trailingAction={
            query ? (
              <TextInput.Action
                ref={attachClearButtonActivationGuard}
                icon={XCircleFillIcon}
                aria-label="Clear search"
                onClick={clearInput}
              />
            ) : undefined
          }
        />
      </div>
    </div>
  )
}
